static inline NQ_List__ast__assignment_fact nq_list__ast__assignment_fact_make(void) {
    return (NQ_List__ast__assignment_fact){ .data = NULL, .len = 0, .cap = 0 };
}
static inline NQUnit nq_list__ast__assignment_fact_push(NQ_List__ast__assignment_fact* items, NQ_ast__assignment_fact value) {
    if (items->len == items->cap) {
        int32_t next_cap = items->cap == 0 ? 4 : items->cap * 2;
        items->data = (NQ_ast__assignment_fact*)nq_realloc(items->data, sizeof(NQ_ast__assignment_fact) * (size_t)next_cap);
        items->cap = next_cap;
    }
    items->data[items->len] = value;
    items->len += 1;
    return NQ_UNIT;
}
